// Eigendeckung hinter dem Zähler bei GEA) [EAG § 75 Abs. 5; Koordinationsstelle; Reichweite unter dem ElWG zu bestätigen].

const SNE = "https://www.ris.bka.gv.at/geltendefassung.wxe?abfrage=bundesnormen&gesetzesnummer=20010107";
const SNE_NEU = "https://www.e-control.at/documents/1785851/0/V+SNE+01_26+SNE-G-V+Begutachtungsentwurf+samt+Erl%C3%A4uterungen.pdf/1425ce2f-897d-bea7-b8e6-e84f67f978ab";
const ALT_BIS = "2026-12-31";
const NEU_AB = "2027-01-01";

const r = (id, d) => ({ id, gueltigAb: "", gueltigBis: "", modelle: [], zonelevel: [], abgabenBefreitModelle: [], quelleUrl: SNE, ...d });

/** @type {import("./modell.js").EgNetzentgeltRegel[]} */
export const NETZENTGELT_REGELN = [
  // ---- bis 31.12.2026 (bezug: modell, EEG lokal = Zonelevel 3, regional = 4/5)
  r("ENR-2026-EEG-LOKAL", { gueltigBis: ALT_BIS, bezug: "modell", modelle: ["eeg"], zonelevel: [3], netzebenen: [6, 7], reduktionPct: 57, abgabenBefreitModelle: ["eeg"], quelle: "SNE-V 2018 § 5 Abs. 1a (EEG lokal, NE 6/7)", status: "gesichert" }),
  r("ENR-2026-EEG-REG-NS", { gueltigBis: ALT_BIS, bezug: "modell", modelle: ["eeg"], zonelevel: [4, 5], netzebenen: [6, 7], reduktionPct: 28, abgabenBefreitModelle: ["eeg"], quelle: "SNE-V 2018 § 5 Abs. 1a (EEG regional, NE 6/7)", status: "gesichert" }),
  r("ENR-2026-EEG-REG-MS", { gueltigBis: ALT_BIS, bezug: "modell", modelle: ["eeg"], zonelevel: [4, 5], netzebenen: [4, 5], reduktionPct: 64, abgabenBefreitModelle: ["eeg"], quelle: "SNE-V 2018 § 5 Abs. 1a (EEG regional, NE 4/5)", status: "gesichert" }),
  r("ENR-2026-GEA", { gueltigBis: ALT_BIS, bezug: "modell", modelle: ["gea"], zonelevel: [1, 2], netzebenen: [7], reduktionPct: 100, abgabenBefreitModelle: ["gea"], quelle: "Eigendeckung hinter dem Netzanschluss ohne Netznutzung (ElWG § 68; Koordinationsstelle)", status: "entwurf" }),
  r("ENR-2026-BEG", { gueltigBis: ALT_BIS, bezug: "modell", modelle: ["beg", "p2p", "eigenversorgung"], zonelevel: [1, 2, 3, 4, 5, 6, 7], netzebenen: [3, 4, 5, 6, 7], reduktionPct: 0, quelle: "SNE-V 2018 § 5 Abs. 1a gilt nur für EEG", status: "gesichert" }),
  // ---- ab 01.01.2027 (bezug: zonelevel) – PLATZHALTER bis zur neuen SNE-VO
  r("ENR-2027-Z1-2", { gueltigAb: NEU_AB, bezug: "zonelevel", zonelevel: [1, 2], netzebenen: [7], reduktionPct: 100, abgabenBefreitModelle: ["eeg", "gea"], quelleUrl: SNE_NEU, quelle: "Arbeitshypothese Fachkonzept 1.3: keine Netzkosten für Eigendeckung (neue SNE-VO)", status: "platzhalter" }),
  r("ENR-2027-Z3", { gueltigAb: NEU_AB, bezug: "zonelevel", zonelevel: [3], netzebenen: [6, 7], reduktionPct: 57, abgabenBefreitModelle: ["eeg"], quelleUrl: SNE_NEU, quelle: "Arbeitshypothese Fachkonzept 1.3 (Lokalbereich, neue SNE-VO)", status: "platzhalter" }),
  r("ENR-2027-Z4-5-NS", { gueltigAb: NEU_AB, bezug: "zonelevel", zonelevel: [4, 5], netzebenen: [6, 7], reduktionPct: 28, abgabenBefreitModelle: ["eeg"], quelleUrl: SNE_NEU, quelle: "Arbeitshypothese Fachkonzept 1.3 (Regionalbereich NE 6/7, neue SNE-VO)", status: "platzhalter" }),
  r("ENR-2027-Z4-5-MS", { gueltigAb: NEU_AB, bezug: "zonelevel", zonelevel: [4, 5], netzebenen: [4, 5], reduktionPct: 64, abgabenBefreitModelle: ["eeg"], quelleUrl: SNE_NEU, quelle: "Arbeitshypothese Fachkonzept 1.3 (Regionalbereich NE 4/5, neue SNE-VO)", status: "platzhalter" }),
  r("ENR-2027-Z6-7", { gueltigAb: NEU_AB, bezug: "zonelevel", zonelevel: [6, 7], netzebenen: [3, 4, 5, 6, 7], reduktionPct: 0, quelleUrl: SNE_NEU, quelle: "Arbeitshypothese Fachkonzept 1.3 (keine Verbindung)", status: "platzhalter" }),
];

const imZeitraum = (x, d) => (!x.gueltigAb || x.gueltigAb <= d) && (!x.gueltigBis || x.gueltigBis >= d);

/**
 * Anwendbare Regel für einen Tag. Ohne Treffer: { regel: null, reduktionPct: 0, … „keine Reduktion“ }.
 * @param {{datum:string, modell:string, zonelevel:number, netzebene:number}} k
 */
export function netzentgeltRegel({ datum, modell, zonelevel, netzebene }, regeln = NETZENTGELT_REGELN) {
  const d = String(datum || "").slice(0, 10);
  const z = Number(zonelevel);
  const ne = Number(netzebene) || 7;
  const treffer = regeln.find((x) => imZeitraum(x, d) && x.netzebenen.includes(ne) && (x.bezug === "modell" ? x.modelle.includes(modell) && (!x.zonelevel.length || x.zonelevel.includes(z)) : x.zonelevel.includes(z)));
  if (!treffer) return { regel: null, reduktionPct: 0, faktor: 0, abgabenBefreit: false, status: "gesichert", quelle: "keine Reduktion", text: "keine Netzentgelt-Reduktion" };
  const pct = treffer.reduktionPct ?? 0;
  return {
    regel: treffer.id, reduktionPct: pct, faktor: pct / 100, abgabenBefreit: treffer.abgabenBefreitModelle.includes(modell), status: treffer.status, quelle: treffer.quelle,
    text: `${pct > 0 ? `−${pct} % Netznutzungs-Arbeitspreis` : "keine Netzentgelt-Reduktion"}${treffer.status === "platzhalter" ? " (Platzhalter bis zur neuen SNE-VO)" : ""}`,
  };
}

/** Kaufmännisch auf 2 Kommastellen (ct/kWh) – SNE-V 2018 § 5 Abs. 1a letzter Satz */
export const rundeCt2 = (x) => Math.sign(x) * Math.round(Math.abs(Number(x) || 0) * 100 + 1e-9) / 100;

/** Reduzierter Netznutzungs-Arbeitspreis in ct/kWh (gerundet) */
export const reduzierterAp = (apCt, reduktionPct) => rundeCt2((Number(apCt) || 0) * (1 - (Number(reduktionPct) || 0) / 100));

/** Regeln, die an einem Stichtag gelten (für Anzeige) */
export const regelnAm = (stichtag, regeln = NETZENTGELT_REGELN) => regeln.filter((x) => imZeitraum(x, String(stichtag || "").slice(0, 10)));
// src/lib/plattform/eg/ersparnis.js
//
// Netzentgelt-, Abgaben- und Energiepreisvorteil je Beleg (Fachkonzept 4.6) – INFORMATIV: Die Reduktion zieht der
// Netzbetreiber bereits auf der Netzrechnung ab (HA II 4); der Beleg weist sie nur als Schätzung aus. Dazu die
// Energieherkunft der Gemeinschaftserzeugung. Reine Funktionen; Python-Spiegel: plattform/eg_abrechnung_kern.py.
//
// Quellen: SNE-V 2018 § 5 Abs. 1a (Regeltabelle eg/netzentgelt.js, Rundung auf 2 Kommastellen), EAG § 75 Abs. 5
// (Erneuerbaren-Förderbeitrag, arbeitsbezogener Teil), Elektrizitätsabgabegesetz (Satz 2026 (zu bestätigen)),
// Elektrizitätsabgabe-Eigenstrombefreiungsverordnung; Befreiungsreichweite unter dem ElWG (zu bestätigen).

import { rund2 } from "../mitglied/basis.js";
import { netzentgeltRegel, reduzierterAp } from "./netzentgelt.js";
import { ANLAGE_ARTEN } from "./modell.js";

/** Ordnung nach Codepunkten (gleiches Ergebnis in JS und Python) */
const vgl = (a, b) => (a < b ? -1 : a > b ? 1 : 0);

/** Elektrizitätsabgabe in ct/kWh – Werte (zu bestätigen), Fachkonzept 4.6 */
export const ELEKTRIZITAETSABGABE = [
  { gueltigAb: "2026-01-01", gueltigBis: "2026-12-31", haushaltCt: 0.1, sonstCt: 0.82, status: "zu_bestaetigen", quelle: "Senkung der Elektrizitätsabgabe 2026 (EY Steuernachrichten) (zu bestätigen)" },
  { gueltigAb: "2027-01-01", gueltigBis: "", haushaltCt: 1.5, sonstCt: 1.5, status: "platzhalter", quelle: "Fachkonzept 9 Punkt 5: Satz 2027 offen (zu bestätigen)" },
];
export const ERSPARNIS_TEXT = "Ihr Vorteil durch die Energiegemeinschaft (Schätzung, die Abrechnung erfolgt durch Ihren Netzbetreiber)";

const imZeitraum = (x, d) => (!x.gueltigAb || x.gueltigAb <= d) && (!x.gueltigBis || x.gueltigBis >= d);

/** Arbeitspreis Netznutzung des Netzbetreibers (ct/kWh) am Tag für die Netzebene; null = nicht gepflegt */
export function netzApFuer(netzbetreiber, datum, netzebene, ersatzCt = null) {
  const d = String(datum || "").slice(0, 10);
  const ne = Number(netzebene) || 7;
  const t = (netzbetreiber?.netzentgeltAp || []).filter((x) => Number(x.netzebene) === ne && String(x.gueltigAb || "") <= d).sort((a, b) => vgl(String(b.gueltigAb), String(a.gueltigAb)))[0];
  if (t) return { ct: Number(t.ctKwh), quelle: `${netzbetreiber.kurzname || netzbetreiber.id}, gültig ab ${t.gueltigAb}` };
  if (ersatzCt !== null && ersatzCt !== undefined && ersatzCt !== "") return { ct: Number(ersatzCt), quelle: "Annahme der Gemeinschaft (Einstellungen) – bitte mit der Netzrechnung abgleichen" };
  return { ct: null, quelle: "Netznutzungs-Arbeitspreis des Netzbetreibers nicht gepflegt" };
}

/**
 * Ersparnis einer Verbrauchsposition.
 * @param {{eigendeckungKwh:number, datum:string, modell:string, zonelevel:number, netzebene:number, netzApCt:number|null,
 *          haushalt:boolean, bezugspreisCt:number, lieferantPreisCt:number|null, efbApCt:number|null}} e
 */
export function ersparnisBerechnen({ eigendeckungKwh = 0, datum, modell, zonelevel, netzebene = 7, netzApCt = null, haushalt = true, bezugspreisCt = 0, lieferantPreisCt = null, efbApCt = null } = {}) {
  const kwh = Number(eigendeckungKwh) || 0;
  const regel = netzentgeltRegel({ datum, modell, zonelevel, netzebene });
  const quellen = [regel.quelle];
  let netzEur = null;
  let reduziertCt = null;
  if (netzApCt !== null && netzApCt !== undefined) {
    reduziertCt = reduzierterAp(netzApCt, regel.reduktionPct);
    netzEur = rund2((kwh * (Number(netzApCt) - reduziertCt)) / 100);
  }
  let abgabeEur = 0;
  let efbEur = 0;
  let abgabeCt = 0;
  if (regel.abgabenBefreit) {
    const ea = ELEKTRIZITAETSABGABE.find((x) => imZeitraum(x, String(datum).slice(0, 10)));
    abgabeCt = ea ? (haushalt ? ea.haushaltCt : ea.sonstCt) : 0;
    abgabeEur = rund2((kwh * abgabeCt) / 100);
    if (ea) quellen.push(ea.quelle);
    if (efbApCt !== null && efbApCt !== undefined) efbEur = rund2((kwh * Number(efbApCt)) / 100);
  }
  const energieEur = lieferantPreisCt !== null && lieferantPreisCt !== undefined ? rund2((kwh * (Number(lieferantPreisCt) - Number(bezugspreisCt))) / 100) : null;
  const summe = rund2((netzEur || 0) + abgabeEur + efbEur + (energieEur || 0));
  return {
    regel: regel.regel, reduktionPct: regel.reduktionPct, status: regel.status, netzApCt, reduziertCt, netzEur, abgabenBefreit: regel.abgabenBefreit, abgabeCt, abgabeEur, efbEur, energieEur, summeEur: summe,
    text: ERSPARNIS_TEXT, platzhalter: regel.status === "platzhalter", quellen,
  };
}

/** Vorteil des Erzeugers gegenüber dem Marktpreis für Überschuss (Fachkonzept 4.6) */
export function erzeugervorteil({ eingebrachtKwh = 0, einspeisepreisCt = 0, marktpreisCt = null } = {}) {
  if (marktpreisCt === null || marktpreisCt === undefined || marktpreisCt === "") return null;
  return rund2(((Number(eingebrachtKwh) || 0) * (Number(einspeisepreisCt) - Number(marktpreisCt))) / 100);
}

/**
 * Energieherkunft der Gemeinschaftserzeugung im Zeitraum (Anteile je Anlagenart, eingebrachte Menge).
 * @param {{art:string, kwh:number}[]} mengen
 */
export function herkunft(mengen = []) {
  const je = {};
  for (const m of mengen) je[m.art || "pv"] = (je[m.art || "pv"] || 0) + (Number(m.kwh) || 0);
  const summe = Object.values(je).reduce((s, x) => s + x, 0);
  const anteile = Object.entries(je).filter(([, kwh]) => kwh > 0).map(([art, kwh]) => ({ art, label: ANLAGE_ARTEN[art] || art, kwh: Math.round(kwh * 1000) / 1000, pct: summe > 0 ? Math.round((kwh / summe) * 1000) / 10 : 0 })).sort((a, b) => b.kwh - a.kwh);
  const text = anteile.length
    ? `100 % erneuerbare Energie aus Anlagen der Gemeinschaft: ${anteile.map((a) => `${a.label} ${String(a.pct).replace(".", ",")} %`).join(", ")}.`
    : "100 % erneuerbare Energie aus Anlagen der Gemeinschaft (ElWG § 68: gemeinsame Nutzung nur erneuerbarer Energie).";
  return { anteile, summeKwh: Math.round(summe * 1000) / 1000, text, quelle: "ElWG §§ 66–68 (nur erneuerbare Energie); Stromkennzeichnung im Sinn der Lieferantenpflichten (zu bestätigen)" };
}
// src/lib/rechner/energySharing.js
//
// Energy-Sharing-/Energiegemeinschafts-Rechner für DE, AT und CH.
// Reine Funktionen ohne React:
//
//   node src/lib/rechner/energySharing.js      → Selbsttest
//
// Methodik (Näherung, offen gelegt):
//  - Erzeugung = kWp × spezifischer Ertrag der Region.
//  - Geteilter Strom: Nur was zeitgleich (Viertelstunde) erzeugt UND verbraucht
//    wird, zählt. Näherung über eine Sättigungskurve:
//        geteilt = Verbrauch × a · (1 − e^(−R/a)),  R = Erzeugung / Verbrauch
//    Kleine Anlagen werden fast vollständig genutzt (geteilt ≈ Erzeugung), große
//    stoßen an die Gleichzeitigkeitsgrenze a (Anteil des Verbrauchs, der
//    überhaupt in Sonnenstunden anfällt – abhängig vom Teilnehmermix, mit
//    Speicher höher).
//  - Vorteil je geteilter kWh für Teilnehmende = Energiepreis des Lieferanten −
//    Gemeinschaftspreis + Netzentgeltabschlag (AT/CH) + entfallende Abgaben (AT).
//  - Erzeuger: Gemeinschaftspreis für geteilten Strom, Überschuss zur Vergütung.
// Standardwerte je Land aus GEMEINSCHAFTEN.rechner (markt.js).

import { GEMEINSCHAFTEN, REGIONEN } from "../invest/markt.js";

export const LAENDER = [
  { id: "de", label: "Deutschland", sub: "Energy Sharing" },
  { id: "at", label: "Österreich", sub: "EEG / BEG" },
  { id: "ch", label: "Schweiz", sub: "LEG" },
];

/** Gleichzeitigkeit: Anteil des Verbrauchs, der maximal zeitgleich mit PV gedeckt werden kann – eigene Näherung */
export const MIXE = [
  { id: "haushalte", label: "Haushalte", sub: "abends viel Verbrauch", a: 0.35 },
  { id: "gemischt", label: "Gemischt", sub: "Haushalte + Betriebe", a: 0.45 },
  { id: "gewerbe", label: "Gewerbe", sub: "tagsüber aktiv", a: 0.6 },
];
export const SPEICHER_PLUS = 0.12;

export const land = (id) => GEMEINSCHAFTEN.rechner[id] || GEMEINSCHAFTEN.rechner.de;
export const regionenFuer = (id) => REGIONEN.filter((r) => r.land === id.toUpperCase());

export function standardFuer(landId) {
  const l = land(landId);
  const regionen = regionenFuer(landId);
  return {
    land: landId,
    regionId: (regionen.find((r) => r.id === "de-sued") || regionen[0]).id,
    rabattId: l.rabatte[0].id,
